function Card({ title, children }) {
  return (
    <div className="card">
      <h3>{title}</h3>
      {children}
    </div>
  );
}

export default function App() {
  const fruits = ["Cam", "Xoài", "Ổi"];
  return (
    <div>
      <Card title="Trái cây">
        <ul>
          {fruits.map((f) => (
            <li key={f}>{f}</li>
          ))}
        </ul>
      </Card>
    </div>
  );
}

